solution.solution.ts:
function parseScores(text: string): number[] {
  return text
    .split(",")
    .map(part => part.trim())
    .filter(part => part !== "" && Number.isFinite(Number(part)))
    .map(Number);
}

function stats(values: number[]): [number, number, number] | null {
  if (values.length === 0) return null;
  const sum = values.reduce((a, b) => a + b, 0);
  return [Math.min(...values), Math.max(...values), sum / values.length];
}

function describe(value: unknown): string {
  if (typeof value === "string") return `text of length ${value.length}`;
  if (typeof value === "number") return `number ${value}`;
  if (Array.isArray(value)) return `list of ${value.length} items`;
  if (value === null || value === undefined) return "nothing";
  return "something else";
}

unitTests:
test("parsing scores", () => {
  checkEq(parseScores("3, 5,x, 8"), [3, 5, 8]);
  checkEq(parseScores(""), []);
  checkEq(parseScores(" -1.5 , , 2e2"), [-1.5, 200]);
});

test("stats as a tuple", () => {
  checkEq(stats([4, 1, 7]), [1, 7, 4]);
  checkEq(stats([2]), [2, 2, 2]);
  checkEq(stats([]), null);
});

test("describing unknown values", () => {
  checkEq(describe("hey"), "text of length 3");
  checkEq(describe(3.5), "number 3.5");
  checkEq(describe([1, 2]), "list of 2 items");
  checkEq(describe(null), "nothing");
  checkEq(describe(undefined), "nothing");
  checkEq(describe({}), "something else");
});

